CREATE TABLE otp_tokens (id BIGINT NOT NULL AUTO_INCREMENT, user_id BIGINT NOT NULL, mobile_or_email VARCHAR(180) NOT NULL, purpose VARCHAR(40) NOT NULL, delivery_channel VARCHAR(20) NOT NULL, otp_code_hash VARCHAR(255) NOT NULL, expires_at TIMESTAMP(6) NOT NULL, verified_at TIMESTAMP(6) NULL, attempt_count INT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY (id), KEY idx_otp_tokens_user (user_id), KEY idx_otp_tokens_identifier (), KEY idx_otp_tokens_purpose_expiry (purpose, expires_at), CONSTRAINT fk_otp_tokens_user FOREIGN KEY (user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
